INSERT INTO `canonical_question` VALUES (64,'READING','ac14f6afcb3869531307131699fd0ac689f10c59d5fee90655bc54ee4f3250f7','Il dort.','Il travaille.','Il joue.','Il mange.','B','A1','2026-05-04 05:30:14'),(65,'READING','47a9e2950dfb1940f63d08dc5c7dd8151ee6888932cb563924f39d8fcd271143','Annoncer un changement.','Décrire un endroit.','Donner un rendez-vous.','Organiser une réunion.','A','A1','2026-05-04 05:30:14'),(66,'READING','245d1a86e7fb56310c9c40a26fe427c0faba8608f79c5d62d7439a56efe71cb7','Professionnelles.','Familiales.','Amicales.','Commerciales.','C','A1','2026-05-04 05:30:14'),(67,'READING','f4555d2d83bfb875884b6d84d3e35f73506330a329cde06d58d04ba7038371eb','Il va avoir de nouveaux horaires.','Il va changer de propriétaire.','Il va déménager en septembre.','Il va fermer pendant l’été.','D','A1','2026-05-04 05:30:14'),(68,'READING','ce59674b4f3ab6f64e48716e6fdba199b1c11d98d2eb666c30e629db465b6aea','Canadienne.','Espagnole.','Italienne.','Mexicaine.','B','A2','2026-05-04 05:30:14'),(69,'READING','4f09158151f331a184210e98ad4aaaa48459b92635106041eb62d33b94c9d1c5','Ils vont bientôt déménager.','Ils vont faire des travaux.','Ils vont organiser une soirée.','Ils vont recevoir de la visite.','B','A2','2026-05-04 05:30:14'),(70,'READING','26741e644509f1c5f79ceca5d0780bda57164306106eef61ca2e7f6dcf82d794','La retraite de ses parents.','Son anniversaire de mariage.','Un nouveau logement.','Une création d’entreprise.','C','A2','2026-05-04 05:30:14'),(71,'READING','9c77e6b52687cd6c8574bd1df9564584fd4624280cafc6266f7b4ae5285f7a1d','Offrir des emplois.','Participer à un forum.','Présenter leur action.','Trouver de l’argent.','A','A2','2026-05-04 05:30:14'),(72,'READING','76f606e8a222523be98f9d9ac3d9afeac9e7979c1797034728e6a9a16c133e7f','Un document professionnel.','Un titre de transport.','Une enveloppe timbrée.','Une somme d’argent.','A','A2','2026-05-04 05:30:14'),(73,'READING','3a889070d40e2f5affa12799895fedc0b3df2e4a8d23149c1b0d68d318d8e9f4','Des cours de cuisine.','Des men