--
-- Table structure for table `question`
--

DROP TABLE IF EXISTS `question`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `question` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `exam_set_id` bigint NOT NULL,
  `canonical_question_id` bigint NOT NULL,
  `sequence_order` int NOT NULL,
  `question_no` varchar(20) DEFAULT NULL,
  `passage` text,
  `question_text` varchar(500) NOT NULL,
  `option_a` varchar(300) NOT NULL,
  `option_b` varchar(300) NOT NULL,
  `option_c` varchar(300) NOT NULL,
  `option_d` varchar(300) NOT NULL,
  `correct_answer` char(1) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `exam_set_id` (`exam_set_id`),
  KEY `fk_question_canonical_question` (`canonical_question_id`),
  CONSTRAINT `fk_question_canonical_question` FOREIGN KEY (`canonical_question_id`) REFERENCES `canonical_question` (`id`),
  CONSTRAINT `question_ibfk_1` FOREIGN KEY (`exam_set_id`) REFERENCES `exam_set` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1641 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

